import { Object3D } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {any} assets
 * @property {string} meshUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Object3D} glbLoader
 * @property {{[key:string]:(target:Object3D,params:any)=>void}} primitives
 * @property {(event:string)=>void} [emit]
 */

/**
 * Creates a thumbnail card node for the Features hub.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // Resolve mesh URL (allow asset wrapper)
  const meshUrl = (config.assets && config.assets.meshUrl) || config.meshUrl;

  // Load GLB (synchronous – cached)
  const source = ctx.glbLoader(meshUrl);
  // Clone to avoid mutating cached instance
  const node = source.clone ? source.clone() : source;

  // Apply transforms
  if (config.position && config.position.length === 3) {
    node.position.set(...config.position);
  }
  if (config.rotation && config.rotation.length === 3) {
    node.rotation.set(...config.rotation);
  }
  if (config.scale && config.scale.length === 3) {
    node.scale.set(...config.scale);
  }

  // Store original Y for hover animation
  const originalY = node.position.y;

  // Hover animation (rise‑in subtle, 0.15 scene units)
  const hoverTimeline = gsap.timeline({ paused: true })
    .to(node.position, {
      y: originalY + 0.15,
      duration: 0.2,
      ease: 'power3.out',
    })
    .to(node.position, {
      y: originalY,
      duration: 0.2,
      ease: 'power3.in',
      onComplete: () => hoverTimeline.pause(),
    });

  // Event handlers attached to userData
  node.userData.handlers = {
    /**
     * Hover handler.
     * @param {boolean} enter true on hover enter, false on leave
     */
    hover(enter) {
      if (enter) {
        hoverTimeline.restart();
      } else {
        hoverTimeline.reverse();
      }
    },
    /**
     * Click handler – emits navigation event.
     */
    click() {
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-features.select');
      }
    },
  };

  // Cleanup routine
  node.userData.cleanup = () => {
    hoverTimeline.kill();
    node.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m && m.dispose && m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  // Apply cinematic primitives defined in the config
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const apply = ctx.primitives[prim.name];
      if (typeof apply === 'function') {
        apply(node, prim.params);
      }
    });
  }

  return node;
}
